import { useEffect, useState } from 'react';
import { Container, Table } from 'react-bootstrap';
import Button from 'react-bootstrap/Button';
import Form from 'react-bootstrap/Form';
import useIsAllowed from './useIsAllowed';

function ControlPanel({projects, setProjects}) {

    useIsAllowed();

    const [isAdding, setIsAdding] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [name, setName] = useState("");
    const [type, setType] = useState("");
    const [hood, setHood] = useState("");
    const [longitude, setLongitude] = useState("");
    const [latitude, setLatitude] = useState("");
    const [success, setSuccess] = useState("");
    const [errorMessage, setErrorMessage] = useState("");
    const [selectedProject, setSelectedProject] = useState("");
    const [originalName, setOriginalName] = useState("");
    const [newHood, setNewHood] = useState("");
    const [hoods, setHoods] = useState("");
    const [hoodList, setHoodList] = useState(false);
    const [selectedHood, setSelectedHood] = useState(false);
    const [originalHoodName, setOriginalHoodName] = useState(false);
    const [isAddHood, setIsAddHood] = useState(false);
    const [isHoodEdit, setIsHoodEdit] = useState(false);

    useEffect(() => {

        fetch("http://localhost:57322/api/hoods")
        .then(res => res.json())
        .then(result => {
            setHoods(result.data);
        })
        .catch(error => console.error(error));

    }, []);

    const handelAddNewHood = (e) => {

        e.preventDefault();

        fetch("http://localhost:57322/api/hood/add", {
            method: "POST",
            headers: {
                "content-type": "application/json",
            },
            body: JSON.stringify({
                name: newHood
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message.includes("تم إضافة")) {
                setSuccess(result.message);
                setHoods(prev => [
                    ...prev, {
                        name: newHood
                    }
                ]);
                setIsAddHood(false);
                setHoodList(true);
                setErrorMessage("");
                setNewHood("");
            } else {
                setErrorMessage(result.message || "حدث خطأ");
                setSuccess("");
            }
        })
        .catch(error => {
            setErrorMessage("فشل الإتصال بالسيرفر");
            setSuccess("");
            console.log(error.message);
        });
    }

    const handelHoodEdit = (e) => {

        e.preventDefault();
        
        fetch("http://localhost:57322/api/hood/edit", {
            method: "POST",
            headers: {
                "Content-type": "application/json"
            },
            body: JSON.stringify({
                originalHoodName,
                name: newHood,
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message === "تم تحديث بيانات الحي بنجاح") {
                setSuccess(result.message);
                setErrorMessage("");
                setHoods(prev =>
                prev.map(hood =>
                    hood.name === originalHoodName
                    ? {
                        ...hood,
                        name,
                        }
                    : hood
                ));
                setIsEditing(false);
                setSelectedHood("");
                setOriginalHoodName("");
            } else {
                setSuccess("");
                setErrorMessage(result.message);
            }
        })
        .catch(error => {
            setSuccess("");
            console.error(error.message);
            setErrorMessage("فشل الإتصال بالسيرفر");
        })

    }
    
    const handelDeleteHood = (hoodName) => {
        const confirmDelete = window.confirm(`هل أنت متأكد من حذف الحي: ${hoodName}`);
        if (!confirmDelete) return;
        fetch("http://localhost:57322/api/hood/delete", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                name: hoodName
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message === "تم حذف الحي بنجاح") {
                setErrorMessage("");
                setSuccess(result.message);
                setHoods(prev => prev.filter(hood => hood.name !== hoodName));
            } else {
                setSuccess("");
                setErrorMessage(result.error);
            }
        })
        .catch(error => {
            setSuccess("");
            setErrorMessage("فشل الإتصال بالسيرفر");
            console.log(error.message);
        })
    }

    const handelAdd = (e) => {
        e.preventDefault();

        fetch("http://localhost:57322/api/project/add", {
            method: "POST",
            headers: {
                "content-type": "application/json",
            },
            body: JSON.stringify({
                name: name,
                type: type,
                hood: hood,
                longitude: longitude,
                latitude: latitude
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message.includes("تم إضافة")) {
                setSuccess(result.message);
                setProjects(prev => [
                    ...prev, {
                        name,
                        sort_type: type,
                        hood,
                        latitude,
                        longitude
                    }
                ]);
                setIsAdding(!isAdding);
                setErrorMessage("");
                setName("");
                setType("");
                setHood("");
                setLatitude("");
                setLongitude("");
            } else {
                setErrorMessage(result.message || "حدث خطأ");
                setSuccess("");
            }
        })
        .catch(error => {
            setSuccess("");
            setErrorMessage("فشل الإتصال بالسيرفر");
            console.log(error.message);
        });
    }

    const handelDelete = (projectName) => {
        const confirmDelete = window.confirm(`هل أنت متأكد من حذف معاملة: ${selectedProject}`);
        if (!confirmDelete) return;
        fetch("http://localhost:57322/api/project/delete", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                name: projectName
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message === "تم حذف المعاملة بنجاح") {
                setErrorMessage("");
                setSuccess(result.message);
                setProjects(prev => prev.filter(project => project.name !== projectName));
            } else {
                setSuccess("");
                setErrorMessage(result.error);
            }
        })
        .catch(error => {
            setSuccess("");
            setErrorMessage("فشل الإتصال بالسيرفر");
            console.log(error.message);
        })
    }

    const handelEdit = (e) => {

        e.preventDefault();
        
        fetch("http://localhost:57322/api/project/edit", {
            method: "POST",
            headers: {
                "Content-type": "application/json"
            },
            body: JSON.stringify({
                originalName,
                name,
                type,
                hood,
                latitude,
                longitude
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message === "تم تعديل المعاملة بنجاح") {
                setSuccess(result.message);
                setErrorMessage("");
                setProjects(prev =>
                prev.map(project =>
                    project.name === originalName
                    ? {
                        ...project,
                        name,
                        hood,
                        sort_type: type,
                        latitude,
                        longitude
                        }
                    : project
                ));
                setIsEditing(false);
                setSelectedProject("");
                setOriginalName("");
                setName("");
                setType("");
                setHood("");
                setLatitude("");
                setLongitude("");
            } else {
                setSuccess("");
                setErrorMessage(result.message);
            }
        })
        .catch(error => {
            setSuccess("");
            console.error(error.message);
            setErrorMessage("فشل الإتصال بالسيرفر");
        })

    }

  return (
    <Container>
    {success && <div className='alert alert-success text-center mt-3'>{success}</div>}
    {errorMessage && <div className='alert alert-warning text-center mt-3'>{errorMessage}</div>}
        {isAdding?  (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>إضافة معاملة</h5>
                <Form onSubmit={handelAdd} style={{maxWidth: "600px", margin: "auto"}}>
                    <Form.Group className="mb-2" controlId="formBasicEmail">
                        <Form.Label>إسم المعاملة</Form.Label>
                        <Form.Control onChange={(e) => setName(e.target.value)} type="text" placeholder="أكتب إسم المعاملة" />
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>نوع العقار</Form.Label>
                        <Form.Select value={type} onChange={(e) => setType(e.target.value)}>
                            <option>...</option>
                            {[...new Set(projects?.map((project) => project['sort_type']))].map((type, index) => (
                                <option key={index}>{type}</option>
                            ))}
                        </Form.Select>
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>اسم الحي</Form.Label>
                        <Form.Select value={hood} onChange={(e) => setHood(e.target.value)}>
                            <option>...</option>
                            {hoods?.map((hood) => {
                                return <option key={hood.id} value={hood.name}>{hood.name}</option>
                            })}
                        </Form.Select>
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>خط الطول</Form.Label>
                        <Form.Control onChange={(e) => setLongitude(e.target.value)} placeholder="يجب أن يكون DD" type='number'/>
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>دائرة العرض</Form.Label>
                        <Form.Control onChange={(e) => setLatitude(e.target.value)} placeholder="يجب أن يكون DD" type='number'/>
                    </Form.Group>
                    <div className='d-flex justify-content-between'>
                    <Button variant="primary" type="submit">
                        حفظ
                    </Button>
                        <Button onClick={() => {
                            setIsAdding(!isAdding);
                            setErrorMessage("");
                            setSuccess("");
                        }} 
                        variant='secondary'>
                            عودة
                        </Button>
                    </div>
                </Form>
            </>

        ) : isEditing? (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>تعديل معاملة {selectedProject}</h5>
                <Form onSubmit={handelEdit} style={{maxWidth: "600px", margin: "auto"}}>
                    <Form.Group className="mb-2" controlId="formBasicEmail">
                        <Form.Label>إسم المعاملة</Form.Label>
                        <Form.Control value={name}  onChange={(e) => setName(e.target.value)} type="text" placeholder="أكتب إسم المعاملة" />
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>نوع العقار</Form.Label>
                        <Form.Select value={type} onChange={(e) => setType(e.target.value)}>
                            <option>...</option>
                            {[...new Set(projects?.map((project) => project['sort_type']))].map((type, index) => (
                                <option key={index}>{type}</option>
                            ))}
                        </Form.Select>
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>اسم الحي</Form.Label>
                        <Form.Select value={hood} onChange={(e) => setHood(e.target.value)}>
                            <option>...</option>
                            {hoods?.map((hood) => {
                                return <option key={hood.id} value={hood.name}>{hood.name}</option>
                            })}
                        </Form.Select>
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>خط الطول</Form.Label>
                        <Form.Control value={longitude} onChange={(e) => setLongitude(e.target.value)} placeholder="يجب أن يكون DD" type='number'/>
                    </Form.Group>

                    <Form.Group className='mb-2'>
                        <Form.Label>دائرة العرض</Form.Label>
                        <Form.Control value={latitude} onChange={(e) => setLatitude(e.target.value)} placeholder="يجب أن يكون DD" type='number'/>
                    </Form.Group>
                    <div className='d-flex justify-content-between'>
                        <Button variant="primary" type="submit">
                            حفظ
                        </Button>
                        <Button onClick={() => {
                            setIsEditing(false);
                            setSelectedProject("");
                            setOriginalName("");
                            setName("");
                            setType("");
                            setHood("");
                            setLatitude("");
                            setLongitude("");
                            setErrorMessage("");
                            setSuccess("");
                        }} 
                        variant='secondary'>
                            عودة
                        </Button>
                    </div>
                </Form>
            </>
        ) : hoodList? (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>قائمة الأحياء</h5>
                    <Table striped bordered hover responsive>
                    <thead>
                        <tr>
                        <th>إسم الحي</th>
                        <th>التحكم</th>
                        </tr>
                    </thead>
                    <tbody>
                        {hoods?.map((hood) => {
                            return (
                                <tr key={hood.id}>
                                    <td>{hood.name}</td>
                                    <td className='m-auto'>
                                        <Button onClick={() => {
                                            setSelectedHood(hood.name);
                                            setNewHood(hood.name);
                                            setHoodList(false);
                                            setIsHoodEdit(true);
                                        }} 
                                            className='m-1'
                                            variant='info'>
                                                <i className='fa fa-edit'></i>
                                        </Button>

                                        <Button onClick={() => {
                                            handelDeleteHood(hood.name);
                                            }} 
                                            variant='danger'>
                                                <i className='fa fa-close'></i>
                                        </Button>
                                    </td>
                                </tr>
                            )
                        })}

                    </tbody>
                    </Table>
                    <Button className='mb-3' onClick={() => {
                        setIsAddHood(true);
                        setHoodList(false);
                    } } >إضافة</Button>
            </>
        ) : isAddHood? (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>إضافة حي جديد</h5>
                <Form onSubmit={handelAddNewHood} style={{maxWidth: "600px", margin: "auto"}}>
                    <Form.Group className="mb-2">
                        <Form.Label>إسم الحي</Form.Label>
                        <Form.Control onChange={(e) => setNewHood(e.target.value)} type="text" placeholder="أكتب إسم الحي" />
                    </Form.Group>
                    <Button 
                        className='ms-1'
                        type='submit'
                        >إضافة حي</Button>
                </Form>
            </>
        ) : isHoodEdit? (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>تعديل الحي {selectedHood}</h5>
                <Form onSubmit={handelHoodEdit} style={{maxWidth: "600px", margin: "auto"}}>
                    <Form.Group className="mb-2">
                        <Form.Label>إسم الحي</Form.Label>
                        <Form.Control onChange={(e) => setNewHood(e.target.value)} type="text" placeholder="أكتب إسم الحي" />
                    </Form.Group>
                    <div className='d-flex justify-content-between'>
                        <Button variant="primary" type="submit">
                            حفظ
                        </Button>
                        <Button onClick={() => {
                            setIsHoodEdit(false);
                            setHoodList(true);
                            setSelectedHood("");
                            setOriginalHoodName("");
                            setErrorMessage("");
                            setSuccess("");
                        }} 
                        variant='secondary'>
                            عودة
                        </Button>
                    </div>
                </Form>
            </>
        ) : (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>جدول المعاملات</h5>
                    <Table striped bordered hover responsive>
                    <thead>
                        <tr>
                        <th>إسم المعاملة</th>
                        <th>نوع العقار</th>
                        <th>إسم الحي</th>
                        <th>التحكم</th>
                        </tr>
                    </thead>
                    <tbody>
                        {projects?.map((project) => {
                            return (
                                <tr key={project.id}>
                                    <td>{project.name}</td>
                                    <td>{project['sort_type']}</td>
                                    <td>{project.hood}</td>
                                    <td className='m-auto'>
                                        <Button onClick={() => {
                                            setSelectedProject(project.name);
                                            setOriginalName(project.name);
                                            setName(project.name);
                                            setHood(project.hood);
                                            setType(project['sort_type']);
                                            setLatitude(project['latitude']);
                                            setLongitude(project['longitude']);
                                            setIsEditing(!isEditing);
                                        }} 
                                            className='m-1' variant='info'><i className='fa fa-edit'></i></Button>
                                        <Button onClick={() => {
                                            handelDelete(project.name);
                                            }} variant='danger'><i className='fa fa-close'></i></Button>
                                    </td>
                                </tr>
                            )
                        })}

                    </tbody>
                    </Table>
                    <div className='d-flex justify-content-between'>
                        <Button className='mb-3' onClick={() => setIsAdding(true)}>إضافة معاملة</Button>
                        <Button variant='info' className='mb-3' onClick={() => setHoodList(true)}>إضافة حي</Button>
                    </div>
            </>
        )}
    </Container>

  );
}

export default ControlPanel;