import { useEffect, useState } from "react";
import { Button, Container, Form, Table } from "react-bootstrap";
import useIsAllowed from "./useIsAllowed";

function Users() {
    
    useIsAllowed();

    const [isAdding, setIsAdding] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [name, setName] = useState("");
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [role, setRole] = useState("");
    const [success, setSuccess] = useState("");
    const [error, setError] = useState("");
    const [selectedUser, setSelectedUser] = useState("");
    const [users, setUsers] = useState([]);


    useEffect(() => {

        fetch("http://localhost:57322/api/users", {method : "GET"})
        .then(res => res.json())
        .then(result => {
            if (result.message && result.message.includes("خطأ")) {
                setError(result.message);
            } else {
                setUsers(result.data);
            }
        })
    }, []);

    const handelAdd = (e) => {
        e.preventDefault();

        fetch("http://localhost:57322/api/user/insert", {
            method: "POST",
            headers: {
                "content-type": "application/json",
            },
            body: JSON.stringify({
                name: name,
                email: email,
                password: password,
                role: role,
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message.includes("تم إضافة")) {
                setSuccess(result.message);
                setUsers(prev => [
                    ...prev, {
                        name,
                        email,
                        password,
                        role
                    }
                ]);
                setIsAdding(false);
                setError("");
                setName("");
                setEmail("");
                setPassword("");
                setRole("");
            } else {
                setError(result.message || "حدث خطأ");
                setSuccess("");
            }
        })
        .catch(error => {
            setError("فشل الإتصال بالسيرفر");
            setSuccess("");
            console.log(error);
        });
    }

    const handelDelete = () => {
        const confirmDelete = window.confirm(`هل أنت متأكد من حذف معاملة: ${selectedUser}`);
        if (!confirmDelete) return;
        fetch("http://localhost:57322/api/user/delete", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                name: name
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message === "تم حذف المستخدم بنجاح") {
                setSuccess(result.message);
                setError("");
                setUsers(prev => prev.filter(user => user.email !== selectedUser));
            } else {
                setError(result.error);
            }
        })
        .catch(error => {
            setError("فشل الإتصال بالسيرفر");
            setSuccess("");
            console.error(error);
        })
    }

    const handelEdit = (e) => {

        e.preventDefault();
        
        fetch("http://localhost:57322/api/user/update", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                name: name,
                email: email,
                password: password,
                role: role,
            })
        }).then(res => res.json())
        .then(result => {
            if (result.message && result.message === "تم تعديل المستخدم بنجاح") {
                setSuccess(result.message);
                setError("");
                setUsers(prev => 
                    prev.map(user =>
                        user.email === selectedUser ? { ...user, name, email, password, role } : user
                    ));
            } else {
                setError(result.message);
                setSuccess("");
            }
        })
        .catch(error => {
            console.error(error);
            setError(error);
        })

    }

return (
    <Container>
        {success && <div className='alert alert-success text-center mt-3'>{success}</div>}
        {error && <div className='alert alert-warning text-center mt-3'>{error}</div>}
            {isAdding?  (
                <>
                    <h5 className='text-primary mt-5 mb-3 text-center'>إضافة مستخدم</h5>
                    <Form onSubmit={handelAdd} style={{maxWidth: "600px", margin: "auto"}}>
                        <Form.Group className="mb-2">
                            <Form.Label>إسم المستخدم</Form.Label>
                            <Form.Control onChange={(e) => setName(e.target.value)} type="text" placeholder="أكتب إسم المستخدم" />
                        </Form.Group>
                        
                        <Form.Group className="mb-2">
                            <Form.Label>البريد الإلكتروني</Form.Label>
                            <Form.Control onChange={(e) => setEmail(e.target.value)} type="email" placeholder="أكتب البريد الإلكتروني" />
                        </Form.Group>

                        <Form.Group className="mb-2">
                            <Form.Label>كلمة المرور</Form.Label>
                            <Form.Control onChange={(e) => setPassword(e.target.value)} type="password" placeholder="أكتب كلمة المرور" />
                        </Form.Group>

                        <Form.Group className='mb-2'>
                            <Form.Label>الوظيفة</Form.Label>
                            <Form.Select value={role} onChange={(e) => setRole(e.target.value)}>
                                <option>...</option>
                                <option value={"محرر"}>محرر</option>
                                <option value={"مدير"}>مدير</option>
                            </Form.Select>
                        </Form.Group>

                        <div className='d-flex justify-content-between'>
                            <Button variant="primary" type="submit">
                                حفظ
                            </Button>
                            <Button onClick={() => {
                                setIsAdding(false);
                                setError("");
                                setSuccess("");
                            }} 
                            variant='secondary'>
                                عودة
                            </Button>
                        </div>
                    </Form>
                </>

            ) : isEditing? (
                <>
                    <h5 className='text-primary mt-5 mb-3 text-center'>تعديل {selectedUser}</h5>
                    <Form onSubmit={handelEdit} style={{maxWidth: "600px", margin: "auto"}}>
                        <Form.Group className="mb-2">
                            <Form.Label>إسم المستخدم</Form.Label>
                            <Form.Control value={name}  onChange={(e) => setName(e.target.value)} type="text" placeholder="أكتب إسم المستخدم" />
                        </Form.Group>

                        <Form.Group className="mb-2">
                            <Form.Label>البريد الإلكتروني</Form.Label>
                            <Form.Control value={email}  onChange={(e) => setEmail(e.target.value)} type="text" placeholder="أكتب البريد الإلكتروني" />
                        </Form.Group>

                        <Form.Group className="mb-2">
                            <Form.Label>كلمة المرور</Form.Label>
                            <Form.Control onChange={(e) => setPassword(e.target.value)} type="password" placeholder="أكتب كلمة المرور" />
                        </Form.Group>

                        <Form.Group className='mb-2'>
                            <Form.Label>الوظيفة</Form.Label>
                            <Form.Select value={role} onChange={(e) => setRole(e.target.value)}>
                                <option>...</option>
                                <option value={"محرر"}>محرر</option>
                                <option value={"مدير"}>مدير</option>
                            </Form.Select>
                        </Form.Group>

                        <div className='d-flex justify-content-between'>
                            <Button variant="primary" type="submit">
                                حفظ
                            </Button>
                            <Button onClick={() => {
                                setIsEditing(!isEditing);
                                setError("");
                                setSuccess("");
                            }} 
                            variant='secondary'>
                                عودة
                            </Button>
                        </div>
                    </Form>
                </>
            ) : (
                <>
            <h5 className='text-primary mt-5 mb-3 text-center'>جدول المستخدمين</h5>
                <Table striped bordered hover responsive>
                <thead>
                    <tr>
                    <th>إسم المستخدم</th>
                    <th>البريد الإلكتروني</th>
                    <th>الوظيفة</th>
                    <th>التحكم</th>
                    </tr>
                </thead>
                <tbody>
                    {users?.map((user) => {
                        return (
                            <tr key={user.id}>
                                <td>{user.name}</td>
                                <td>{user.email}</td>
                                <td>{user.role}</td>
                                <td className='m-auto'>
                                    <Button onClick={() => {
                                        setSelectedUser(user.email);
                                        setName(user.name);
                                        setEmail(user.email);
                                        setRole(user.role);
                                        setIsEditing(!isEditing);
                                    }} 
                                        className='m-1' variant='info'><i className='fa fa-edit'></i></Button>
                                    <Button onClick={() => {
                                        setSelectedUser(user.email);
                                        setEmail(user.email);
                                        handelDelete();
                                        }} variant='danger'><i className='fa fa-close'></i></Button>
                                </td>
                            </tr>
                        )
                    })}

                </tbody>
                </Table>
                <Button onClick={() => setIsAdding(true)}>إضافة</Button>
                </>
            )}
    </Container>
)

}

export default Users;