import { useState } from "react"
import { Button, Form } from "react-bootstrap";
import { useNavigate } from "react-router";

function Login() {
    
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error ,setError] = useState("");
    const [success ,setSuccess] = useState("");
    const navigate = useNavigate();

    const handelAdd = (e) => {
        e.preventDefault();

        if (!email || !password) {
            return setError("يرجى كتابة البريد الإلكتروني وكلمة المرور");
        }

        fetch("http://localhost:57322/api/login",
             {method: "POST", 
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    email: email,
                    password: password
        })})
        .then(async res => {
             const data = await res.json();
             if (!res.ok) {
                 setError("");
                 setError(data.message || "حدث خطأ حاول مرة أخرى");
             } else {
                 setSuccess(data.message);
                 sessionStorage.setItem("user", JSON.stringify({
                     name: data.data.name,
                     email: data.data.email,
                     role: data.data.role,
                     created_at: data.data.created_at,
                     updated_at: data.data.updated_at
                 }))
                 navigate("/");
             }})
        .catch(error => console.error(error));

    }

    return (
            <>
                <h5 className='text-primary mt-5 mb-3 text-center'>إضافة معاملة</h5>
                {error? (
                    <>
                    <div className="alert alert-warning mx-auto mb-3 text-center" style={{maxWidth: "600px"}}>{error}</div>
                    </>
                ) : null}
                {success? (
                    <>
                    <div className="alert alert-success mx-auto mb-3 text-center" style={{maxWidth: "600px"}}>{success}</div>
                    </>
                ) : null}
                <Form onSubmit={handelAdd} style={{maxWidth: "600px", margin: "auto"}}>
                    <Form.Group className="mb-2" controlId="formBasicEmail">
                        <Form.Label>البريد الإلكتروني</Form.Label>
                        <Form.Control onChange={(e) => setEmail(e.target.value)} type="email" placeholder="أكتب البريد الإلكتروني" />
                    </Form.Group>
                    <Form.Group className="mb-2">
                        <Form.Label>كلمة المرور</Form.Label>
                        <Form.Control onChange={(e) => setPassword(e.target.value)} type="password" placeholder="أكتب كلمة المرور" />
                    </Form.Group>
                    <Button type="submit">تسجيل الدخول</Button>
                </Form>
            </>
    )
}

export default Login;