import { Bounce } from "react-awesome-reveal";
import { Card, Col, Container, Row } from "react-bootstrap";
import MyPieChart from "./Charts/MyPieChart";
import MyParChart from "./Charts/MyParChart";
function Stats({projects = []}) {  

    return (
        <Container>
            <h4 className="text-center my-5 ">الإحصائات</h4>
            <Row className="text-center">
                <Col sm="10" md="10" className="m-auto">
                    <Card bg="primary" className="text-light">
                        <Card.Body>
                            <Bounce>
                                <h1>{projects.length || 0}</h1>
                            </Bounce>
                            <Card.Text>
                                عدد المعاملات
                            </Card.Text>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
            <Row className="mt-3">
                <Bounce>
                    <MyPieChart projects={projects}/>
                </Bounce>
            </Row>
            <Row className="mt-3">
                <Bounce>
                    <MyParChart projects={projects}/>
                </Bounce>
            </Row>
        </Container>
    )
}

export default Stats;

