import { LayersControl, MapContainer, Marker, Popup, TileLayer } from "react-leaflet";
import 'leaflet/dist/leaflet.css';
import L from "leaflet";
import { useEffect, useRef } from "react";

const {BaseLayer} = LayersControl;

function MyMap({projects, selectedProject}) {

    const mapRef = useRef();
    const markerRef = useRef({});

    const projectIcon = L.icon({
        iconUrl: "project_icon1.png",
        iconSize: [40, 40],
    });

    useEffect(() => {

        if (selectedProject && mapRef.current) {
            
            const marker = markerRef.current[selectedProject.id];
            const map = mapRef.current;

            if (marker && map) {

                map.flyTo(marker.getLatLng(), 17);

                marker.openPopup();

            }
        }
    }, [selectedProject]);
    
    return (
        <MapContainer 
            className="my-map rounded"
            center={[24.774265, 46.738586]}
            zoom={10}
            whenCreated={(map) => (mapRef.current = map)}
            ref={mapRef}
            >
            <LayersControl>
                <BaseLayer name="OpenStreetMap" checked>
                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>
                </BaseLayer>
                <BaseLayer name="Esri Satellite">
                    <TileLayer url="https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"/>
                </BaseLayer>
            </LayersControl>
            {projects?.map((project) => {
                return <Marker 
                    key={project.id}
                    position={[project.longitude, project.latitude]}
                    icon={projectIcon}
                    ref={(ref) => (markerRef.current[project.id] = ref)}>
                        <Popup>
                            <div style={{textAlign: "right"}}>
                                <strong>المعاملة:</strong> {project.name} <br/>
                                <strong>الحي: </strong> {project.hood} <br/>
                                <strong>نوع العقار: </strong> {project['sort_type']}
                            </div>
                        </Popup>
                    </Marker>
            })}
        </MapContainer>
    )
}

export default MyMap;