import * as React from 'react';
import { PieChart } from '@mui/x-charts/PieChart';

function MyPieChart({ projects }) {
  // تجميع عدد المعاملات حسب الحي
  const sortTypeCount = {};

  projects?.forEach((project) => {
    const sortType = project['sort_type'] || "غير محدد";
    sortTypeCount[sortType] = (sortTypeCount[sortType] || 0) + 1;
  });

  // تحويله إلى الشكل الذي يحتاجه MUI PieChart
  const data = Object.entries(sortTypeCount).map(([sortType, count], index) => ({
    id: index,
    value: count,
    label: sortType,
  }));


  return (
    <PieChart
      series={[
        {
          data,
          highlightScope: { fade: 'global', highlight: 'item' },
          faded: { innerRadius: 30, additionalRadius: -30, color: 'gray' },
        },
      ]}
      height={200}
      width={200}
    />
  );
}

export default MyPieChart;
