import * as React from 'react';
import { BarChart } from '@mui/x-charts/BarChart';

export default function MyBarChart({ projects }) {
  const hoodCounts = {};

  projects?.forEach((project) => {
    const hood = project.hood || "غير محدد";
    hoodCounts[hood] = (hoodCounts[hood] || 0) + 1;
  });

  const hoods = Object.keys(hoodCounts);
  const values = Object.values(hoodCounts);

  return (
    <BarChart
      xAxis={[{ data: hoods, scaleType: 'band', label: 'الأحياء' }]}
      series={[
        {
          data: values,
          label: 'عدد المعاملات',
          color: '#0d6efd', // لون موحد للأعمدة - أو غيره
          labelPlacement: 'inside', // النص داخل العمود
          labelVisibility: true,     // إظهار النص
        },
      ]}
      // barWidth={30}
    />
  );
}
