import { Col, Row } from "react-bootstrap";
import ProjectList from "./ProjectList";
import MyMap from "./MyMap";
import Stats from "./Stats";

function Home({ projects, setSelectedProject, selectedProject }) {

return (
    <>
        <Row>
            <Col className='p-1' md={3} xs={12}>
                <ProjectList 
                projects={projects} 
                onSelect={(project) => {
                setSelectedProject(project);
                }}/>
            </Col>
            <Col className='p-0' md={6} xs={12}>
                <MyMap 
                projects={projects} 
                selectedProject={selectedProject} />
            </Col>
            <Col className='p-1' md={3} xs={12}>
                <Stats 
                projects={projects}/>
            </Col>
        </Row>
    </>
)
}

export default Home;