import { useEffect, useState } from 'react';
import Container from 'react-bootstrap/Container';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import { Link, useLocation } from 'react-router-dom';

function MyNav() {

  const [userSession, setUserSession] = useState("");
  const location = useLocation();

  useEffect(() => {

    const user = sessionStorage.getItem("user");

    setUserSession(user);

  }, [location])


  return (
    <Navbar expand="lg" variant='dark' bg='primary'>
      <Container>
        <Navbar.Brand as={Link} to="/">معاملات قمة الهرم</Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            {userSession? (
              <>
              <Nav.Link as={Link} to="/control">لوحة التحكم</Nav.Link>
              <Nav.Link as={Link} to="/users">المستخدمين</Nav.Link>
              <Nav.Link as={Link} to="/logout">تسجيل الخروج</Nav.Link>
              </>
            ): (
              <Nav.Link as={Link} to="/login">تسجيل الدخول</Nav.Link>
            )}
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default MyNav;