import { useState } from 'react';
import { Button, Col, Form } from 'react-bootstrap';
import ListGroup from 'react-bootstrap/ListGroup';

function ProjectList({projects, onSelect}) {

  const [searchTerm, setSearchTerm] = useState("");
  
  const handelSubmit = (e) => {
    e.preventDefault();
  }

  const filteredProjects = projects?.filter((project) => {

    return project.name.includes(searchTerm);

  });

  return (
    <ListGroup as="ul" className='project-list overflow-auto my-3 m-auto'>
        <Col>
        <ListGroup.Item as="li" className='bg-primary text-light mb-2 rounded'>
            المعاملات
        <Form onSubmit={handelSubmit} className='d-flex mt-2'>
            <Form.Control
            type="text"
            placeholder="أكتب إسم المعاملة..."
            className="mr-sm-2"
            onChange={(e) => setSearchTerm(e.target.value)}
            value={searchTerm}
            />
            <Button className='btn btn-info me-1' type="submit">بحث</Button>
        </Form>
        </ListGroup.Item>
      </Col>
      {filteredProjects?.map((project) => {
        return <div>
          <ListGroup.Item 
            onClick={() => {
              onSelect(project)
            }} 
            key={project.id} 
            as="li"
            action>
              - {project.name}
          </ListGroup.Item>
        </div> 
      })}
    </ListGroup>
  );
}

export default ProjectList;